package com.beeboee.magnot.region;import com.beeboee.magnot.Magnot;import net.minecraft.nbt.*;import net.minecraft.util.math.BlockPos;import net.minecraft.util.math.vector.Vector3d;import net.minecraft.world.server.ServerWorld;import net.minecraft.world.storage.WorldSavedData;import java.util.*;public final class FerrousRegionSavedData extends WorldSavedData{private static final String NAME=Magnot.MOD_ID+"_ferrous_regions";private final List<FerrousRegion> regions=new ArrayList<FerrousRegion>();private transient Map<Long,List<FerrousRegion>> index;public FerrousRegionSavedData(){super(NAME);}public static FerrousRegionSavedData get(ServerWorld level){return level.getDataStorage().computeIfAbsent(FerrousRegionSavedData::new,NAME);}@Override public void load(CompoundNBT tag){regions.clear();ListNBT list=tag.getList("Regions",10);for(int i=0;i<list.size();i++)regions.add(FerrousRegion.load(list.getCompound(i)));index=null;}@Override public CompoundNBT save(CompoundNBT tag){ListNBT list=new ListNBT();for(FerrousRegion r:regions)list.add(r.save());tag.put("Regions",list);return tag;}public List<FerrousRegion> regions(){return Collections.unmodifiableList(regions);}public void addRegion(FerrousRegion r){removeRegion(r.id());regions.add(r);changed();}public boolean removeRegion(UUID id){boolean removed=regions.removeIf(r->r.id().equals(id));if(removed)changed();return removed;}public Optional<FerrousRegion> removeIntersectingById(UUID id,Vector3d a,Vector3d b){for(int i=0;i<regions.size();i++){FerrousRegion r=regions.get(i);if(r.id().equals(id)&&r.intersects(a,b)){regions.remove(i);changed();return Optional.of(r);}}return Optional.empty();}public boolean containsPoint(Vector3d p){for(FerrousRegion r:candidates(p,p))if(r.contains(p))return true;return false;}public boolean blocksMagnet(Vector3d a,Vector3d b){for(FerrousRegion r:candidates(a,b))if(r.intersects(a,b))return true;return false;}private Collection<FerrousRegion> candidates(Vector3d a,Vector3d b){ensureIndex();Set<FerrousRegion> result=new LinkedHashSet<FerrousRegion>();for(int x=sec(Math.min(a.x,b.x));x<=sec(Math.max(a.x,b.x));x++)for(int y=sec(Math.min(a.y,b.y));y<=sec(Math.max(a.y,b.y));y++)for(int z=sec(Math.min(a.z,b.z));z<=sec(Math.max(a.z,b.z));z++){List<FerrousRegion> list=index.get(key(x,y,z));if(list!=null)result.addAll(list);}return result;}private void ensureIndex(){if(index!=null)return;index=new HashMap<Long,List<FerrousRegion>>();for(FerrousRegion r:regions)for(int x=sec(r.min().getX());x<=sec(r.max().getX());x++)for(int y=sec(r.min().getY());y<=sec(r.max().getY());y++)for(int z=sec(r.min().getZ());z<=sec(r.max().getZ());z++)index.computeIfAbsent(key(x,y,z),q->new ArrayList<FerrousRegion>()).add(r);}private void changed(){index=null;FerrousMagnetRules.invalidateCaches();setDirty();}private static int sec(double v){return Math.floorDiv((int)Math.floor(v),16);}private static long key(int x,int y,int z){return((long)x&0x3ffffffL)<<38|((long)z&0x3ffffffL)<<12|((long)y&0xfffL);}}
